// ---- images.js
// ---- 3d render images + glass ui helpers ---------------------------------------
const IMG = {};

function imagePaint(name, mode) {
  if (!ASSETS[name]) throw new Error('missing asset: ' + name);
  if (!IMG[name]) IMG[name] = figma.createImage(figma.base64Decode(ASSETS[name]));
  return { type: 'IMAGE', scaleMode: mode || 'FILL', imageHash: IMG[name].hash };
}

// the full-frame render behind a screen. named "bg" in every frame so smart animate can zoom it
function bgImage(parent, name) {
  return rect(parent, 0, 0, 1440, 900, { fill: imagePaint(name), name: 'bg' });
}

// the same render, pushed in on a region (the camera-move target) and optionally blurred
function zoomBg(parent, name, region, zoom, blur) {
  const cx = region.x + region.w / 2;
  const cy = region.y + region.h / 2;
  const n = rect(parent, 720 - cx * zoom, 450 - cy * zoom, 1440 * zoom, 900 * zoom, { fill: imagePaint(name), name: 'bg' });
  if (blur) n.effects = [{ type: 'LAYER_BLUR', radius: blur, visible: true }];
  return n;
}

function dim(parent, alpha, color) {
  return rect(parent, 0, 0, 1440, 900, { fill: color || '#02050b', op: alpha, name: 'dim' });
}

// frosted panel: translucent fill, hairline border, background blur
function glass(parent, x, y, w, h, o) {
  o = o || {};
  const fx = [{ type: 'BACKGROUND_BLUR', radius: o.blur || 18, visible: true }];
  if (o.glow) fx.push(glow(o.glow, o.glowR || 24, o.glowA || 0.3));
  if (o.shadow !== false) fx.push(shadow(10, 28, 0.45));
  const n = rect(parent, x, y, w, h, {
    fill: o.fill || '#07101e',
    op: o.op === undefined ? 0.62 : o.op,
    r: o.r === undefined ? 16 : o.r,
    fx,
    name: o.name || 'glass',
  });
  n.strokes = [{ type: 'SOLID', color: rgb(o.stroke || '#9fc4ff'), opacity: o.strokeOp === undefined ? 0.28 : o.strokeOp }];
  n.strokeWeight = o.sw || 1.2;
  n.strokeAlign = 'INSIDE';
  return n;
}

// a hotspot placed over a 3d object's screen region
function hotRegion(parent, region, name, pad, minSize) {
  pad = pad === undefined ? 14 : pad;
  minSize = minSize || 64;
  let x = region.x - pad;
  let y = region.y - pad;
  let w = region.w + pad * 2;
  let h = region.h + pad * 2;
  if (w < minSize) { x -= (minSize - w) / 2; w = minSize; }
  if (h < minSize) { y -= (minSize - h) / 2; h = minSize; }
  x = Math.max(0, x);
  y = Math.max(0, y);
  w = Math.min(w, 1440 - x);
  h = Math.min(h, 900 - y);
  return hotspot(parent, x, y, w, h, name);
}

// ---- art.js
// ---- shared art: stars + planet (for close-ups), HUD, toast, props ------------

function drawStars(parent, seed, count, x0, y0, w, h) {
  const r = rng(seed);
  for (let i = 0; i < count; i++) {
    const s = r() < 0.12 ? 3 : r() < 0.4 ? 2 : 1;
    ellipse(parent, x0 + r() * w, y0 + r() * h, s, s, {
      fill: r() < 0.15 ? C.cyan : C.white,
      op: 0.25 + r() * 0.75,
      name: 'star',
    });
  }
}

function drawPlanet(parent, x, y, d) {
  ellipse(parent, x - d * 0.12, y - d * 0.12, d * 1.24, d * 1.24, {
    fill: radial([
      [0.7, '#27d3ff', 0.0],
      [1, '#27d3ff', 0.18],
    ]),
    name: 'atmosphere',
  });
  ellipse(parent, x, y, d, d, {
    fill: [linear([[0, '#1b4f9c'], [0.55, '#0d2a5c'], [1, '#050c1d']], 125)],
    name: 'planet',
  });
  const r = rng(7);
  for (let i = 0; i < 5; i++) {
    const bw = d * (0.3 + r() * 0.4);
    ellipse(parent, x + r() * (d - bw), y + d * (0.15 + i * 0.15), bw, d * 0.05, {
      fill: '#5db4ff',
      op: 0.1 + r() * 0.12,
      name: 'cloud',
    });
  }
}

function pulse(parent, x, y, col) {
  ellipse(parent, x - 22, y - 22, 44, 44, { fill: radial([[0, col, 0.55], [1, col, 0]]), name: 'glint' });
  ellipse(parent, x - 4, y - 4, 8, 8, { fill: col, fx: [glow(col, 12, 0.9)], name: 'glint core' });
}

function porthole(parent, x, y, d, seed) {
  const g = frame(parent, x, y, d, d, { noclip: true, name: 'porthole' });
  ellipse(g, -10, -10, d + 20, d + 20, {
    fill: linear([[0, '#2b3d5e'], [1, '#0d1626']], 45),
    stroke: '#3a5282',
    sw: 2,
    fx: [shadow(8, 18, 0.6)],
    name: 'porthole rim',
  });
  const inner = frame(g, 0, 0, d, d, { name: 'porthole view' });
  inner.cornerRadius = d / 2;
  inner.fills = [solid('#02040a')];
  drawStars(inner, seed, 40, 0, 0, d, d);
  drawPlanet(inner, d * 0.2, d * 0.45, d * 0.9);
  ellipse(g, 0, 0, d, d, { fill: linear([[0, '#ffffff', 0.18], [0.4, '#ffffff', 0]], 45), name: 'glass' });
  return g;
}

function hazardStripe(parent, x, y, w, h) {
  const g = frame(parent, x, y, w, h, { fill: '#171a22', name: 'hazard' });
  const step = h * 1.6;
  for (let i = -2; i < w / step + 2; i++) {
    path(g, i * step, 0, 'M ' + step * 0.5 + ' 0 L ' + step + ' 0 L ' + (step * 0.5 + h) + ' ' + h + ' L 0 ' + h + ' Z', { fill: C.amber, op: 0.92, name: 'stripe' });
  }
  return g;
}

function drawKeycard(parent, x, y, w, name) {
  const h = w * 0.64;
  const g = frame(parent, x, y, w, h, {
    noclip: true,
    fill: linear([[0, '#2b7bff'], [1, '#0b2d7a']], 45),
    stroke: '#9fd0ff',
    sw: 1.5,
    r: w * 0.09,
    fx: [glow('#27d3ff', w * 0.4, 0.7)],
    name: name || 'keycard',
  });
  rect(g, 0, h * 0.2, w, h * 0.18, { fill: '#000000', op: 0.55, name: 'stripe' });
  rect(g, w * 0.1, h * 0.58, w * 0.22, h * 0.26, { fill: '#ffd23b', r: 3, name: 'chip' });
  text(g, w * 0.4, h * 0.6, 'LVL 2', { font: 'head', size: Math.max(7, w * 0.11), fill: C.white, name: 'level' });
  return g;
}

// ---- HUD ----------------------------------------------------------------------

function hud(parent, roomLabel, o2, held, hint) {
  rect(parent, 0, 0, W, 78, {
    fill: linear([[0, '#000000', 0.7], [1, '#000000', 0]], 90),
    name: 'hud shade',
  });
  text(parent, 36, 24, 'STATION OMEGA-7', { font: 'mono', size: 13, fill: C.cyan, ls: 4, name: 'hud / station' });
  text(parent, 256, 24, '//  ' + roomLabel, { font: 'mono', size: 13, fill: '#a9c3e6', ls: 3, name: 'hud / room' });

  const low = o2 <= 10;
  const col = low ? C.red : o2 <= 30 ? C.amber : C.cyan;
  glass(parent, W - 36 - 372, 14, 372, 40, { r: 20, op: 0.5, shadow: false, name: 'o2 glass' });
  text(parent, W - 36 - 352, 24, 'O2', { font: 'head', size: 13, fill: col, ls: 3, name: 'hud / o2 label' });
  rect(parent, W - 36 - 312, 31, 252, 8, { fill: '#ffffff', op: 0.1, r: 4, name: 'o2 track' });
  rect(parent, W - 36 - 312, 31, Math.max(8, 252 * (o2 / 100)), 8, { fill: col, r: 4, fx: [glow(col, 10, 0.9)], name: 'o2 fill' });
  text(parent, W - 36 - 54, 24, o2 + '%', { font: 'head', size: 13, fill: col, w: 40, align: 'RIGHT', name: 'hud / o2 pct' });

  const iy = H - 96;
  text(parent, 36, iy - 24, 'INVENTORY', { font: 'mono', size: 11, fill: '#a9c3e6', ls: 3, name: 'inv label' });
  for (let i = 0; i < 3; i++) glass(parent, 36 + i * 76, iy, 68, 68, { r: 14, op: 0.5, blur: 14, name: 'inv slot' });
  if (held) drawKeycard(parent, 36 + 9, iy + 20, 50, 'inv / keycard');

  if (hint) {
    glass(parent, 640, 14, 140, 38, { r: 19, op: 0.5, stroke: C.cyan, strokeOp: 0.5, shadow: false, name: 'hint button' });
    text(parent, 640, 14, '?  HINT', { font: 'mono', size: 13, fill: C.cyan, ls: 3, w: 140, align: 'CENTER', lh: 38, name: 'hint label' });
    go(hotspot(parent, 636, 10, 148, 46, 'hint'), hint, { d: 0.2 });
  }
}

function toast(parent, msg, tone) {
  const col = tone === 'bad' ? C.red : tone === 'good' ? C.green : C.cyan;
  const w = 780;
  const g = glass(parent, (W - w) / 2, H - 150, w, 76, { r: 18, op: 0.66, stroke: col, strokeOp: 0.7, glow: col, glowA: 0.28, name: 'toast' });
  rect(parent, (W - w) / 2 + 14, H - 150 + 20, 5, 36, { fill: col, r: 3, fx: [glow(col, 12, 0.8)], name: 'toast bar' });
  text(parent, (W - w) / 2 + 40, H - 150, msg, { font: 'mono', size: 19, fill: C.white, w: w - 70, lh: 76, name: 'toast / text' });
  return g;
}

// ---- flow.js
// ---- frame registry + prototype wiring -------------------------------------
// Links are encoded into layer names ("hotspot / vent → {json}") so that every
// build step can run as its own script; wire() resolves them in a final pass.
const GRID_X = W + 160;
const GRID_Y = H + 200;
const OXYGEN_SECONDS = 150; // idle time before the lungs give out

function mk(key, name, col, row) {
  const f = figma.createFrame();
  f.name = key + ' · ' + name;
  f.resize(W, H);
  f.clipsContent = true;
  f.fills = [solid(C.bg0)];
  f.x = col * GRID_X;
  f.y = row * GRID_Y;
  figma.currentPage.appendChild(f);
  return f;
}

function tag(node, kind, to, o, secs) {
  const spec = Object.assign({ k: kind, to }, secs === undefined ? {} : { s: secs }, o || {});
  node.name = node.name + ' → ' + JSON.stringify(spec);
}

// click -> navigate. `to` is a frame key or 'BACK'
function go(node, to, o) {
  tag(node, 'click', to, o);
}

// timed -> navigate; the reaction lives on the frame, a 1px marker carries the spec
function after(frameNode, secs, to, o) {
  const m = rect(frameNode, 0, 0, 1, 1, { fill: '#000000', op: 0 });
  m.name = 'timer';
  tag(m, 'timer', to, o, secs);
}

function lungs(f) {
  after(f, OXYGEN_SECONDS, 'lose', { d: 1.4 });
}


// ---- ui.js
// ---- shared ui pieces ---------------------------------------------------------

function closeBtn(f, x, y, to, o) {
  glass(f, x, y, 46, 46, { r: 23, op: 0.6, blur: 14, shadow: false, name: 'close' });
  text(f, x, y, '✕', { font: 'bold', size: 18, fill: C.white, w: 46, align: 'CENTER', lh: 46, name: 'close x' });
  go(hotspot(f, x - 6, y - 6, 58, 58, 'close'), to, o || { d: 0.18 });
}

function pill(f, x, y, w, h, label, col, filled) {
  rect(f, x, y, w, h, {
    fill: filled ? col : '#050a14',
    op: filled ? 1 : 0.55,
    stroke: filled ? '#ffffff' : col,
    sw: 2,
    r: h / 2,
    fx: [glow(col, 26, filled ? 0.6 : 0.3), shadow(8, 18, 0.5)],
    name: 'button',
  });
  if (filled) rect(f, x + 3, y + 3, w - 6, h / 2 - 3, { fill: linear([[0, '#ffffff', 0.35], [1, '#ffffff', 0]], 90), r: h / 2, name: 'button sheen' });
  text(f, x, y, label, {
    font: 'head',
    size: Math.round(h * 0.3),
    fill: filled ? '#02121a' : col,
    ls: 4,
    w,
    align: 'CENTER',
    lh: h,
    name: 'button label',
  });
}

// camera push-in used for every close-up
const PUSH = { t: 'SMART_ANIMATE', d: 0.55, ease: 'EASE_IN_AND_OUT' };

// ---- rooms.js
// ---- title + the three rooms (3d renders with live hotspots on top) -------------

function buildTitle() {
  const f = mk('title', '00 / Title', 0, 0);
  bgImage(f, 'title');
  rect(f, 0, 0, 980, 900, { fill: linear([[0, '#02050b', 0.78], [1, '#02050b', 0]], 0), name: 'text shade' });
  text(f, 120, 262, 'A FIGMA ESCAPE ROOM', { font: 'mono', size: 16, fill: C.cyan, ls: 8, name: 'eyebrow' });
  text(f, 112, 300, 'OMEGA-7', { font: 'title', size: 150, fill: C.white, ls: 6, fx: [glow(C.cyan, 40, 0.35)], name: 'title' });
  text(f, 120, 500, 'You wake up alone.\nOxygen is falling. Find the escape pod.', { font: 'body', size: 26, lh: 40, fill: '#a9c3e6', name: 'tagline' });
  pill(f, 120, 640, 320, 76, 'WAKE UP  →', C.cyan, true);
  text(f, 120, 770, 'Present mode.  Click everything.  Trust nothing.', { font: 'mono', size: 14, fill: '#8fa9cc', ls: 2, name: 'hint' });
  go(hotspot(f, 120, 640, 320, 76, 'wake up'), 'q1', { d: 0.9 });
}

// ---- QUARTERS ------------------------------------------------------------------
function buildQuarters(key, name, col, row, s) {
  const f = mk(key, name, col, row);
  const R = REGIONS['quarters_' + s.state];
  bgImage(f, 'quarters_' + s.state);
  hud(f, 'SLEEPING QUARTERS', 18, s.held, 'hq');
  toast(f, s.toast, s.tone);

  go(hotRegion(f, R.bunk, 'bunk', 0), 'diary', PUSH);
  go(hotRegion(f, R.porthole, 'porthole', 8), 'porthole', PUSH);
  go(hotRegion(f, R.poster, 'crew poster', 10), 'poster', PUSH);
  go(hotRegion(f, R.vent, 'vent', 8), s.state === 'open' ? 'q2v' : s.state === 'empty' ? 'q3v' : 'q1v');
  if (s.state === 'closed') go(hotRegion(f, R.locker, 'locker', 6), 'q2');
  if (s.state === 'open') go(hotRegion(f, R.keycard, 'keycard', 34, 96), 'q3');
  if (s.state === 'empty') go(hotRegion(f, R.locker, 'locker (empty)', 6), 'q3l');
  if (s.held) go(hotRegion(f, R.door, 'door', 6), 'c1', { t: 'PUSH', dir: 'LEFT', d: 0.7, ease: 'EASE_IN_AND_OUT' });
  else go(hotRegion(f, R.door, 'door', 6), s.state === 'open' ? 'q2d' : 'q1d');
  lungs(f);
}

function buildAllQuarters() {
  const VENT = 'Too small to crawl through. Nothing in there but dust.';
  const LOCK = 'Magnetic lock. It wants a keycard.';
  buildQuarters('q1', '01 / Quarters', 0, 1, { state: 'closed', held: false, toast: 'Alarms. A throbbing head. Look around: something must open.' });
  buildQuarters('q1v', '01 / Quarters · vent', 1, 1, { state: 'closed', held: false, toast: VENT });
  buildQuarters('q1d', '01 / Quarters · locked door', 2, 1, { state: 'closed', held: false, toast: LOCK, tone: 'bad' });
  buildQuarters('q2', '02 / Quarters · locker open', 0, 2, { state: 'open', held: false, toast: 'The locker pops. Something is glinting on the shelf.', tone: 'good' });
  buildQuarters('q2v', '02 / Quarters · vent', 1, 2, { state: 'open', held: false, toast: VENT });
  buildQuarters('q2d', '02 / Quarters · locked door', 2, 2, { state: 'open', held: false, toast: LOCK, tone: 'bad' });
  buildQuarters('q3', '03 / Quarters · keycard', 0, 3, { state: 'empty', held: true, toast: 'KEYCARD ACQUIRED. LEVEL 2 CLEARANCE', tone: 'good' });
  buildQuarters('q3v', '03 / Quarters · vent', 1, 3, { state: 'empty', held: true, toast: VENT });
  buildQuarters('q3l', '03 / Quarters · empty locker', 2, 3, { state: 'empty', held: true, toast: 'Empty. A dent where the keycard used to be.' });
}

// ---- CONTROL ROOM ----------------------------------------------------------------
function buildControl(key, name, col, row, s) {
  const f = mk(key, name, col, row);
  const R = REGIONS.control_sealed;
  bgImage(f, s.open ? 'control_open' : 'control_sealed');
  hud(f, 'CONTROL ROOM', 11, true, 'hc');
  toast(f, s.toast, s.tone);

  go(hotRegion(f, R.whiteboard, 'whiteboard', 8), 'whiteboard', PUSH);
  if (!s.open) {
    go(hotRegion(f, R.airlock, 'airlock', 4), 'c1a');
    go(hotRegion(f, R.terminal, 'terminal', 10), 'k0', PUSH);
  } else {
    go(hotRegion(f, R.airlock, 'airlock', 4), 'p1', { t: 'PUSH', dir: 'LEFT', d: 0.7, ease: 'EASE_IN_AND_OUT' });
  }
  lungs(f);
}

function buildAllControl() {
  buildControl('c1', '05 / Control room', 0, 4, { open: false, toast: 'Dead consoles. One terminal still has power.' });
  buildControl('c1a', '05 / Control room · airlock', 1, 4, { open: false, toast: 'Airlock sealed. The terminal must control it.', tone: 'bad' });
  buildControl('c2', '08 / Control room · airlock open', 2, 4, { open: true, toast: 'ACCESS GRANTED. Airlock seal released.', tone: 'good' });
}

// ---- POD BAY ---------------------------------------------------------------------------
function buildPod(key, name, col, row, s) {
  const f = mk(key, name, col, row);
  const R = REGIONS[s.ready ? 'pod_ready' : 'pod_dead'];
  bgImage(f, s.ready ? 'pod_ready' : 'pod_dead');
  hud(f, 'ESCAPE POD BAY', 5, true, 'hp');
  toast(f, s.toast, s.tone);

  if (s.ready) {
    go(hotRegion(f, R.hatch, 'hatch', 6), 'l3', { d: 0.3 });
    go(hotRegion(f, R.launchbtn, 'launch', 34, 110), 'l3', { d: 0.3 });
  } else {
    go(hotRegion(f, R.hatch, 'hatch', 6), 'p1h');
    go(hotRegion(f, R.panel, 'launch panel', 0), 'w0', PUSH);
  }
  go(hotRegion(f, R.manual, 'manual', 22, 90), 'manual', PUSH);
  lungs(f);
}

function buildAllPod() {
  buildPod('p1', '09 / Pod bay', 0, 6, { ready: false, toast: 'The pod is here, but its panel is dead. Three wires hang loose.' });
  buildPod('p1h', '09 / Pod bay · hatch', 1, 6, { ready: false, toast: 'Hatch is sealed. There is no power to the pod.', tone: 'bad' });
  buildPod('p2', '12 / Pod bay · powered', 2, 6, { ready: true, toast: 'ALL SYSTEMS ONLINE. Launch when ready.', tone: 'good' });
}

// ---- puzzles.js
// ---- the two puzzles: airlock keypad and pod wiring ------------------------------

function symbol(f, kind, cx, cy, s, col) {
  if (kind === 'circle') ellipse(f, cx - s / 2, cy - s / 2, s, s, { fill: col, fx: [glow(col, 10, 0.6)], name: 'sym circle' });
  else if (kind === 'tri') path(f, cx - s / 2, cy - s / 2, 'M ' + s / 2 + ' 0 L ' + s + ' ' + s + ' L 0 ' + s + ' Z', { fill: col, fx: [glow(col, 10, 0.6)], name: 'sym triangle' });
  else rect(f, cx - s / 2, cy - s / 2, s, s, { fill: col, r: 4, fx: [glow(col, 10, 0.6)], name: 'sym square' });
}

function innerShadow(y, radius, alpha) {
  return { type: 'INNER_SHADOW', color: { r: 1, g: 1, b: 1, a: alpha }, offset: { x: 0, y }, radius, spread: 0, visible: true, blendMode: 'NORMAL' };
}

// ---- KEYPAD ----------------------------------------------------------------------
function buildKeypad(key, name, col, row, st) {
  const f = mk(key, name, col, row);
  const bad = st === 'deny';
  const good = st === 'ok';
  const tone = good ? C.green : bad ? C.red : C.cyan;
  zoomBg(f, 'control_sealed', REGIONS.control_sealed.terminal, 2.8, 18);
  dim(f, 0.55, bad ? '#2a0508' : '#02050b');
  glass(f, 400, 70, 640, 760, { r: 32, op: 0.74, blur: 24, stroke: tone, strokeOp: 0.55, glow: tone, glowA: 0.22, glowR: 50, name: 'terminal body' });
  rect(f, 424, 94, 592, 712, { fill: '#050b14', op: 0.55, r: 22, name: 'bezel inner' });
  text(f, 420, 116, 'AIRLOCK 03  ·  PIN ENTRY', { font: 'mono', size: 15, fill: '#a9c3e6', ls: 4, w: 600, align: 'CENTER', name: 'header' });
  rect(f, 480, 170, 480, 110, { fill: '#02090f', stroke: tone, sw: 2, r: 14, fx: [glow(tone, 26, 0.4), innerShadow(4, 14, 0.12)], name: 'display' });
  const slots = !good && !bad;
  if (slots) {
    for (let i = 0; i < 2; i++) {
      const filled = i === 0 && st !== 'k0';
      ellipse(f, 720 + (i ? 52 : -52) - 18, 225 - 18, 36, 36, filled ? { fill: tone, fx: [glow(tone, 16, 0.8)], name: 'digit slot' } : { stroke: tone, sw: 3, op: 0.7, name: 'digit slot' });
    }
  }
  const shown = good ? 'ACCESS GRANTED' : bad ? 'ACCESS DENIED' : '';
  if (shown) text(f, 480, 170, shown, { font: 'head', size: 32, fill: tone, ls: 3, w: 480, align: 'CENTER', lh: 110, fx: [glow(tone, 16, 0.8)], name: 'display text' });
  const sub = good ? 'SEAL RELEASED' : bad ? 'WRONG PIN · RESETTING' : 'ENTER THE 2-DIGIT PIN';
  text(f, 420, 298, sub, { font: 'mono', size: 14, fill: bad ? C.red : '#a9c3e6', ls: 4, w: 600, align: 'CENTER', name: 'sub' });

  const rows = [['1', '2', '3'], ['4', '5', '6'], ['7', '8', '9'], ['CLR', '0', '']];
  rows.forEach((r, ri) =>
    r.forEach((label, ci) => {
      if (!label) return;
      const x = 541 + ci * 124;
      const y = 350 + ri * 84;
      rect(f, x, y, 110, 70, {
        fill: linear([[0, '#2c4572'], [1, '#101a30']], 90),
        stroke: '#6f95d6',
        sw: 1.5,
        r: 16,
        fx: [shadow(8, 12, 0.6), innerShadow(2, 3, 0.35)],
        name: 'key ' + label,
      });
      rect(f, x + 4, y + 4, 102, 26, { fill: linear([[0, '#ffffff', 0.22], [1, '#ffffff', 0]], 90), r: 13, name: 'key sheen' });
      text(f, x, y, label, { font: 'head', size: label === 'CLR' ? 16 : 28, fill: label === 'CLR' ? C.amber : C.white, w: 110, align: 'CENTER', lh: 70, ls: label === 'CLR' ? 2 : 0, name: 'key label' });
    })
  );
  text(f, 420, 716, 'MAINTENANCE TERMINAL  ·  AUTH REQUIRED', { font: 'mono', size: 12, fill: '#a9c3e6', ls: 3, w: 600, align: 'CENTER', op: 0.7, name: 'footer' });

  if (st === 'k0' || st === 'k5' || st === 'kx') {
    rows.forEach((r, ri) =>
      r.forEach((label, ci) => {
        if (!label) return;
        const h = hotspot(f, 541 + ci * 124, 350 + ri * 84, 110, 70, 'key ' + label);
        let to;
        if (label === 'CLR') to = 'k0';
        else if (st === 'k0') to = label === '5' ? 'k5' : 'kx';
        else if (st === 'k5') to = label === '6' ? 'kok' : 'kdeny';
        else to = 'kdeny';
        go(h, to, { d: 0.05 });
      })
    );
    closeBtn(f, 960, 100, 'c1', PUSH);
    lungs(f);
  } else if (bad) after(f, 1.4, 'k0', { d: 0.15 });
  else after(f, 1.6, 'c2', { d: 0.5 });
}

function buildAllKeypad() {
  buildKeypad('k0', '07 / Keypad', 0, 5, 'k0');
  buildKeypad('k5', '07 / Keypad · one digit (right)', 1, 5, 'k5');
  buildKeypad('kx', '07 / Keypad · one digit (wrong)', 2, 5, 'kx');
  buildKeypad('kdeny', '07 / Keypad · denied', 3, 5, 'deny');
  buildKeypad('kok', '07 / Keypad · granted', 4, 5, 'ok');
}

// ---- WIRING ---------------------------------------------------------------------------
const WIRES = [
  { name: 'RED', col: '#ff3b4e', port: 1 },
  { name: 'BLUE', col: '#3b9bff', port: 2 },
  { name: 'YELLOW', col: '#ffd23b', port: 0 },
];
const PORT_SYM = ['circle', 'tri', 'square'];

function buildWire(key, name, col, row, st) {
  const f = mk(key, name, col, row);
  const short = st === 'short';
  const active = short ? 0 : st;
  zoomBg(f, 'pod_dead', REGIONS.pod_dead.panel, 2.0, 18);
  dim(f, short ? 0.5 : 0.55, short ? '#2a0508' : '#02050b');
  glass(f, 180, 100, 1080, 700, { r: 28, op: 0.72, blur: 24, glow: C.cyan, glowA: 0.14, name: 'panel' });
  hazardStripe(f, 200, 118, 1040, 14);
  text(f, 230, 150, 'POD POWER  ·  MANUAL WIRING', { font: 'mono', size: 15, fill: '#a9c3e6', ls: 4, name: 'title' });
  const w0 = WIRES[Math.min(active, 2)];
  const msg = short ? 'SHORT CIRCUIT  ·  RESETTING' : 'CONNECT THE ' + w0.name + ' WIRE';
  const mcol = short ? C.red : w0.col;
  text(f, 230, 186, msg, { font: 'head', size: 30, fill: mcol, ls: 3, fx: [glow(mcol, 18, 0.6)], name: 'instruction' });

  const portY = [250, 430, 610];
  WIRES.forEach((w, i) => {
    const y = 250 + i * 180;
    const done = !short && i < st;
    const isActive = !short && i === st;
    rect(f, 250, y, 80, 90, { fill: w.col, op: isActive || done ? 1 : 0.35, r: 14, fx: isActive ? [glow(w.col, 28, 0.8)] : [], name: 'source ' + w.name });
    text(f, 250, y, w.name.slice(0, 1), { font: 'head', size: 26, fill: '#10131c', w: 80, align: 'CENTER', lh: 90, name: 'source label' });
    if (done) {
      curve(f, 330, y + 45, 1050, portY[w.port] + 45, { stroke: w.col, sw: 10, cap: 'ROUND', fx: [glow(w.col, 14, 0.7)], name: 'wire connected' });
    } else {
      const op = isActive ? 1 : 0.35;
      curve(f, 330, y + 45, 640, y + 62, { stroke: w.col, sw: 10, cap: 'ROUND', op, fx: isActive ? [glow(w.col, 14, 0.7)] : [], name: 'wire loose' });
      rect(f, 640, y + 40, 62, 44, { fill: '#c3d4e6', op, r: 8, name: 'plug' });
      rect(f, 700, y + 48, 18, 10, { fill: '#7d93b8', op, name: 'prong' });
      rect(f, 700, y + 66, 18, 10, { fill: '#7d93b8', op, name: 'prong' });
      if (isActive) text(f, 740, y + 52, '←  ACTIVE', { font: 'mono', size: 15, fill: w.col, ls: 3, name: 'active tag' });
    }
  });
  portY.forEach((y, p) => {
    const used = !short && WIRES.some((w, i) => i < st && w.port === p);
    glass(f, 1050, y, 160, 90, { r: 16, op: 0.7, blur: 10, stroke: used ? C.green : '#9fc4ff', strokeOp: used ? 0.9 : 0.35, glow: used ? C.green : undefined, glowA: 0.4, shadow: false, name: 'port ' + p });
    symbol(f, PORT_SYM[p], 1130, y + 45, 34, used ? C.green : '#e8f4ff');
  });

  pill(f, 230, 716, 230, 48, 'OPEN MANUAL', C.cyan, false);
  go(hotspot(f, 230, 716, 230, 48, 'manual button'), 'manual', { d: 0.25 });
  if (!short) {
    portY.forEach((y, p) => {
      const ok = p === WIRES[st].port;
      go(hotspot(f, 1040, y - 10, 180, 110, 'port ' + p), ok ? (st === 2 ? 'p2' : 'w' + (st + 1)) : 'wshort', { d: ok ? 0.25 : 0.08 });
    });
    closeBtn(f, 1190, 118, 'p1', PUSH);
    lungs(f);
  } else after(f, 1.3, 'w0', { d: 0.2 });
}

function buildAllWires() {
  buildWire('w0', '11 / Wiring · red', 0, 7, 0);
  buildWire('w1', '11 / Wiring · blue', 1, 7, 1);
  buildWire('w2', '11 / Wiring · yellow', 2, 7, 2);
  buildWire('wshort', '11 / Wiring · short circuit', 3, 7, 'short');
}

